select id, tenant_id, unit_code, unit_name, area_id, unit_type, sort_no, status, created_at, updated_at, deleted from base_unit where tenant_id = #{tenantId} and deleted = 0
and (unit_code like concat('%', #{keyword}, '%') or unit_name like concat('%', #{keyword}, '%'))
and status = #{status}
order by id desc limit #{limit} offset #{offset}

select count(1) from base_unit where tenant_id = #{tenantId} and deleted = 0
and (unit_code like concat('%', #{keyword}, '%') or unit_name like concat('%', #{keyword}, '%'))
and status = #{status}
